const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');let now=0,plays=0,pauses=0;const events={};
const audio={attrs:{},readyState:0,duration:NaN,currentTime:0,paused:true,addEventListener(n,f){events[n]=f},getAttribute(n){return this.attrs[n]??null},set src(v){this.attrs.src=v;this.readyState=0;this.duration=NaN;this.currentTime=0},get src(){return this.attrs.src},pause(){this.paused=true;pauses++},play(){this.paused=false;plays++;return Promise.resolve()}};
